async (request, reply) => {
        const actor = await requireActor(request, db());
        if (scoped && actor.id !== request.params.captainId.toLowerCase())
            throw new ApiFault(403, "captain_profile_forbidden", "Only the Captain can complete their image uploads");
        const result = await inTransaction(db(), async (client) => {
            const row = (await client.query("SELECT * FROM user_asset_uploads WHERE id=$1 AND user_id=$2 FOR UPDATE", [request.params.uploadId, actor.id])).rows[0];
            if (!row)
                throw new ApiFault(404, "asset_upload_not_found", "Upload not found");
            if (row.status === "COMPLETED") {
                const profile = (await client.query(`SELECT ${userColumns} FROM users WHERE id=$1`, [actor.id])).rows[0];
                return { profile: scoped ? captainProfile(profile) : accountView(profile), asset: { id: row.id, kind: row.kind, url: row.public_url }, stagingKey: row.staging_key };
            }
            if (row.expires_at.getTime() <= Date.now())
                throw new ApiFault(410, "asset_upload_expired", "Request a new upload URL");
            const url = await storage().publish(row, row.kind, actor.id, row.id);
            await client.query("UPDATE user_asset_uploads SET status='COMPLETED',public_url=$2,completed_at=now() WHERE id=$1", [row.id, url]);
            const profile = scoped ? (await client.query(`UPDATE users SET
        avatar_url=CASE WHEN $2='avatar' THEN $3 ELSE avatar_url END,
        banner_url=CASE WHEN $2='banner' THEN $3 ELSE banner_url END
        WHERE id=$1 RETURNING ${userColumns}`, [actor.id, row.kind, url])).rows[0]
                : (await client.query(`SELECT ${userColumns} FROM users WHERE id=$1`, [actor.id])).rows[0];
            return { profile: scoped ? captainProfile(profile) : accountView(profile), asset: { id: row.id, kind: row.kind, url }, stagingKey: row.staging_key };
        });
        // A failed cleanup cannot turn a committed profile update into an API error.
        try {
            await storage().discard(result.stagingKey);
        }
        catch {
            app.log.warn("Staging asset cleanup deferred to bucket lifecycle");
