(socket) => {
        const client = { socket, expiresAt: 0, alive: true, messages: 0, window: Date.now(), pending: 0, chain: Promise.resolve() };
        clients.add(client);
        socket.on("pong", () => { client.alive = true; });
        socket.on("error", () => socket.close());
        socket.on("close", () => { clients.delete(client); });
        // Attach synchronously before any authentication or subscription awaits.
        socket.on("message", (raw, binary) => {
            if (Date.now() - client.window > 10_000) {
                client.window = Date.now();
                client.messages = 0;
            }
            if (binary || ++client.messages > 20 || client.pending >= 5) {
                socket.close(1008, "Message limit exceeded");
                return;
            }
            client.pending++;
            client.chain = client.chain.then(async () => {
                const message = JSON.parse(raw.toString());
                if (!message || typeof message !== "object" || Array.isArray(message))
                    throw new Error("invalid_message");
                if (message.type === "authenticate") {
                    // Clear previous identity before switching credentials, including failed reauthentication.
                    client.actor = undefined;
                    client.notifications = undefined;
                    client.expiresAt = 0;
                    if (typeof message.accessToken !== "string")
                        throw new Error("invalid_token");
                    const identity = await privyIdentity(message.accessToken);
                    const actor = (await db().query("SELECT id FROM users WHERE auth_subject=$1", [identity.subject])).rows[0];
                    if (!actor)
                        throw new Error("bootstrap_required");
                    client.actor = actor.id;
                    client.expiresAt = identity.expiresAt * 1000;
                    send(client, { type: "authenticated", expiresAt: new Date(client.expiresAt).toISOString() });
                }
                else if (message.type === "subscribe" && message.channel === "market.prices") {
                    if (message.instruments !== undefined && (!Array.isArray(message.instruments) || message.instruments.some(id => typeof id !== "string")))
                        throw new Error("unsupported_instrument");
                    const instruments = instrumentSubset(message.instruments);
                    const changed = !!client.instruments && (client.instruments.length !== instruments.length || instruments.some(id => !client.instruments.includes(id)));
                    client.freshness = undefined;
                    const snapshot = await market().snapshot();
                    const after = message.after;
                    if (after !== undefined && (typeof after !== "string" || !cursorPattern.test(after)))
                        throw new Error("invalid_cursor");
                    client.instruments = instruments;
                    if (!changed && typeof after === "string" && compareCursor(after, snapshot.firstCursor) >= 0 && compareCursor(after, snapshot.cursor) <= 0) {
                        client.cursor = after;
                        send(client, { type: "subscribed", channel: "market.prices", cursor: after });
                    }
                    else {
                        if (after !== undefined)
                            send(client, { type: "resync_required", channel: "market.prices" });
                        send(client, { type: "snapshot", channel: "market.prices", cursor: snapshot.cursor, prices: selected(client, snapshot.prices) });
                        client.cursor = snapshot.cursor;
                    }
                }
                else if (message.type === "subscribe" && message.channel === "account.notifications") {
                    if (!client.actor || client.expiresAt <= Date.now())
                        throw new Error("authentication_required");
                    const after = message.after ?? "0";
                    if (typeof after !== "string" || !validSequence(after))
                        throw new Error("invalid_cursor");
                    client.notifications = after;
                    send(client, { type: "subscribed", channel: "account.notifications", cursor: after });
                }
                else if (message.type === "unsubscribe") {
                    if (message.channel === "market.prices")
                        client.cursor = undefined;
                    else if (message.channel === "account.notifications")
                        client.notifications = undefined;
                    else
                        throw new Error("unsupported_channel");
                }
                else
                    throw new Error("unsupported_message");
            }).catch(() => send(client, { type: "error", code: "request_rejected", message: "Check authentication, channel and cursor" }))
                .finally(() => { client.pending--; });
        });
        send(client, { type: "hello", mode: "PAPER", channels: ["market.prices", "account.notifications"] });
    }

