pub struct Config {
    pub admin: Pubkey,
    pub usdc_mint: Pubkey,
    pub paused: bool,
    pub bump: u8,
}

pub struct Delegate {
    pub fund: Pubkey,
    pub key: Pubkey,
    /// USDC base units.
    pub max_trade_usd: u64,
    pub daily_volume_usd: u64,
    pub day_start: i64,
    pub day_volume: u64,
    pub bump: u8,
}

pub struct Fund {
    pub captain: Pubkey,
    /// Chosen by the captain; part of the seeds.
    pub fund_id: u64,
    pub share_mint: Pubkey,
    /// `[0]` = USDC; `Pubkey::default()` = empty.
    pub holdings: [Pubkey; MAX_HOLDINGS],
    pub holdings_len: u8,
    /// Mirrors the share mint supply.
    pub total_shares: u64,
    /// USDC base units per 1e6 share units (1_000_000 = $1).
    pub last_price_per_share: u64,
    pub peak_price_per_share: u64,
    pub frozen: bool,
    pub proposal_count: u64,
    pub created_at: i64,
    pub bump: u8,
    /// Start of the rolling 24 h autonomous budget (captain and delegate trades).
    pub window_start: i64,
    /// USD (6 dp) traded autonomously since `window_start`. Votes do not count.
    pub window_volume_usd: u64,
    /// Open Seas fund: may buy T3 tokens. Set at creation, never changed.
    pub open_seas: bool,
    /// Cost of the T3 positions still held, USD (6 dp). Sum of `t3_basis_usd`.
    pub t3_cost_basis_usd: u64,
    /// Start of the current 30-day T3 buy window. Windows follow each other
    /// with no gap, from the fund's creation.
    pub t3_window_start: i64,
    /// USD (6 dp) of T3 buys in the current window.
    pub t3_window_buys_usd: u64,
    /// Cost basis of each holding bought as T3, USD (6 dp), in `holdings` order.
    pub t3_basis_usd: [u64; MAX_HOLDINGS],
    /// USD (6 dp) of T3 buys in the window before the current one.
    pub t3_prev_window_buys_usd: u64,
    /// Slot of the last move of `last_price_per_share`: it moves at most one
    /// step per interval (see `nav::update_breaker`).
    pub last_pps_slot: u64,
}

pub struct Member {
    pub fund: Pubkey,
    pub owner: Pubkey,
    /// High-water mark, USDC base units.
    pub hwm: u64,
    pub joined_at: i64,
    /// Anniversary anchor for the performance fee.
    pub last_fee_at: i64,
    pub last_deposit_ts: i64,
    pub is_captain: bool,
    pub bump: u8,
}

pub struct PolicyParams {
    pub autonomous_bps: u16,
    pub drawdown_bps: u16,
    pub max_slippage_bps: u16,
    pub vote_window_secs: u32,
}

pub struct Policy {
    pub fund: Pubkey,
    pub params: PolicyParams,
    pub pending: PolicyParams,
    /// 0 = none.
    pub pending_eta: i64,
    pub bump: u8,
}

pub struct TokenEntry {
    pub mint: Pubkey,
    pub price_source: PriceSource,
    pub tier: Tier,
    pub decimals: u8,
    /// False until the listing is applied after the timelock.
    pub active: bool,
    pub pending_price_source: PriceSource,
    pub pending_tier: Tier,
    /// 0 = nothing pending.
    pub pending_eta: i64,
    pub bump: u8,
    /// Switchboard only: the slow mark prices, shared by every fund. NAV
    /// reads move them (see `switchboard::next_marks`). Reset when the price
    /// source changes.
    pub marks: Marks,
}

pub struct Marks {
    /// Moves toward the feed value both ways, at most 10% per interval: the
    /// token's EMA. For the `Ema` mode (the record target with `Spot`, so
    /// the peak, last pps and annual fee; and the exit compensation),
    /// `DepositUpperBound` and `High` (`max(spot, mark)`), and the exit fee
    /// price (`min(spot, mark)` + std_dev).
    pub deposit: i128,
    /// Slot of the last step of `deposit` (or the seed). After
    /// `MARK_MAX_IDLE_SLOTS` with no step, the next read reseeds both marks.
    pub deposit_slot: u64,
    /// Drops to the feed value at once when the value is lower; rises at most
    /// 10% per interval. Only for the captain stake (`StakeLowerBound`: T3
    /// caps, captain exit floor) and the breaker trip check (`BreakerCheck`).
    pub low: i128,
    /// Slot of the last rise of `low` (or the seed).
    pub low_slot: u64,
    /// Slot of the last seed: the first read after a listing or a price
    /// source change, or the first read after the marks went idle.
    pub seed_slot: u64,
}

pub struct VenueEntry {
    pub program: Pubkey,
    /// False until an approval is applied after the timelock.
    pub active: bool,
    /// The value `apply_venue` sets.
    pub pending_active: bool,
    /// 0 = nothing pending.
    pub pending_eta: i64,
    pub bump: u8,
}

